    "corp_hero_title": "Scale your team's global fluency",
    "corp_hero_subtitle": "Cohort-based language training built for modern workforces.",
    "corp_cta_chat": "Chat with us",
    "corp_cta_chat_desc": "Speak with our workforce solutions team to design a language cohort plan that matches your company's growth.",
    "corp_features_title": "Why Alimun works for teams",
    "corp_feature_1_title": "Role-specific curricula",
    "corp_feature_1_desc": "Custom vocabulary and scenarios designed specifically for your sales, customer support, or technical teams.",
    "corp_feature_2_title": "Active Cohorts",
    "corp_feature_2_desc": "Employees practice speaking together in small live groups, keeping motivation high and accelerating fluency.",
    "corp_feature_3_title": "HR Progress Dashboard",
    "corp_feature_3_desc": "Track attendance, active speaking time, and AI-graded fluency milestones with transparent, real-time reporting.",
    "corp_tiers_title": "Workforce Solutions",
    "corp_tier_1_title": "Team Cohort",
    "corp_tier_1_desc": "Dedicated cohorts for teams of 5-15. Ideal for departments collaborating internationally.",
    "corp_tier_2_title": "Enterprise License",
    "corp_tier_2_desc": "Full access across your organization with custom schedules, priority support, and custom billing.",
    "corp_form_title": "Workforce Inquiry",
    "corp_form_desc": "Tell us about your team's language training needs and we will get back to you with a custom proposal.",
    "corp_form_company": "Company Name",
    "corp_form_employees": "Number of employees",
    "corp_form_submit": "Request Proposal",
    "careers_hero_title": "Teach from anywhere. Earn on your terms.",
    "careers_hero_subtitle": "Lead live, active conversation cohorts for motivated learners worldwide.",
    "careers_cta_apply": "Apply as teacher",
    "careers_why_title": "Why teach on Alimun?",
    "careers_why_1_title": "Cohort leverage",
    "careers_why_1_desc": "Say goodbye to repeating the same basic private lesson 20 times. Teach a structured group and let the cohort interact.",
    "careers_why_2_title": "AI Grading Assistant",
    "careers_why_2_desc": "Our AI handles vocabulary checking and grammar drills. You focus 100% on live communication and real-time feedback.",
    "careers_why_3_title": "Consistent Revenue",
    "careers_why_3_desc": "Get paid a stable base rate per active cohort. The more your cohorts grow, the more your earnings scale.",
    "careers_process_title": "Vetting Process",
    "careers_process_desc": "We accept less than 5% of applicants to keep our teaching standard premium.",
    "careers_step_1_title": "Online Application",
    "careers_step_1_desc": "Submit your CV, teaching credentials, and a short 2-minute video introduction.",
    "careers_step_2_title": "Practice Audition",
    "careers_step_2_desc": "Lead a 30-minute practice session with a small group of active Alimun students.",
    "careers_step_3_title": "Launch Cohort",
    "careers_step_3_desc": "Complete onboarding, set your hours, and launch your first official conversation cohort.",
    "careers_form_title": "Start Your Application",
    "careers_form_desc": "Fill out the preliminary form to request a teaching slot.",
    "careers_form_language": "What language do you teach?",
    "careers_form_experience": "Years of teaching experience",
    "careers_form_video": "Link to video introduction (Loom, YouTube, etc.)",
    "careers_form_submit": "Submit Application",
    "careers_hero_desc": "Teach on your terms. Alimun pairs live conversation cohorts with AI-powered feedback, automating all grading so you can focus entirely on live student interaction, breakout mentoring, and guiding active practice.",
    "careers_t1_desc": "Designing the cohort curriculum at Alimun was a game-changer. I teach many learners simultaneously without burning out.",
    "careers_t2_desc": "Alimun's AI handles all vocabulary drills and grading. I spend 100% of my class time doing what I love: helping students speak.",
    "careers_t3_desc": "The breakout group model is so much more interactive and energizing than doing repetitive 1:1 sessions all day long.",
    "careers_t4_desc": "Consistent per-cohort rates give me excellent income stability while maintaining a completely flexible schedule.",
    "careers_cta_ready_title": "Ready to teach?",
    "careers_carousel_1": "Tired of repetitive 1:1 classes?",
    "careers_carousel_2": "Want to scale your impact?",
    "careers_carousel_3": "Want a flexible schedule?",
    "careers_carousel_4": "Teach on Alimun.",
    "careers_why_4_title": "Flexible Hours",
    "careers_why_4_desc": "Set your own availability and cohort schedule. Teach from anywhere in the world.",
    "careers_sim_sub_1": "Tired of <span class=\"alimun-cta-highlight\">not making enough money</span> from private 1:1 tutoring?",
    "careers_sim_sub_2": "Most platforms take up to <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">33% commission</span> on your hard work.",
    "careers_sim_sub_3": "At Alimun, the standard is <span class=\"alimun-cta-highlight\">30%</span>.",
    "careers_sim_sub_4": "Plus, our cohort model lets you teach up to <span class=\"alimun-cta-highlight\">15 students</span> at once!",
    "careers_sim_sub_5": "Our AI assistant handles homework grading, so you can <span class=\"alimun-cta-highlight\">focus on teaching</span>.",
    "careers_sim_sub_6": "Earn up to <span class=\"alimun-cta-highlight\">€80/hour</span> with total scheduling flexibility.",
    "careers_sim_sub_7": "Speak fluently. For life. <span class=\"alimun-cta-highlight\">Teach on Alimun</span>.",
    "corporate_hero_title": "corporate solutions",
    "corporate_hero_desc": "Ensure your relocated workforce speaks fluently from day one. Alimun pairs professional-grade, role-specific cohorts with native specialist teachers and AI progress tracking.",
    "corporate_cta_demo": "Request a demo",
    "corporate_why_title": "Workforce fluency",
    "corporate_why_1_title": "Relocation Specialist Teachers",
    "corporate_why_1_desc": "Native language experts specializing in expat integration, local business culture, and professional conversation.",
    "corporate_why_2_title": "Role-Specific Cohorts",
    "corporate_why_2_desc": "Employees learn together in small groups grouped by job function, practicing realistic workplace scenarios.",
    "corporate_why_3_title": "AI-Driven Progress",
    "corporate_why_3_desc": "Our AI engine automates vocabulary drills and grading, maximizing live speaking practice with teachers.",
    "corporate_why_4_title": "HR Admin Dashboard",
    "corporate_why_4_desc": "Track attendance, active speaking hours, and CEFR competency milestones with real-time analytics.",
    "corporate_process_title": "How it works",
    "corporate_step_1_title": "1. Skill Assessment",
    "corporate_step_1_desc": "We evaluate your employees' speaking levels and match them to their relocation destinations.",
    "corporate_step_2_title": "2. Custom Cohorts",
    "corporate_step_2_desc": "Employees join private, corporate conversation cohorts matching their role and language goals.",
    "corporate_step_3_title": "3. Launch & Track",
    "corporate_step_3_desc": "Classes begin on your schedule, and HR receives monthly progress and attendance audits.",
    "corporate_slide_1": "Relocating your <span class=\"alimun-cta-highlight\">team abroad</span>?",
