    "lt_seo_title": "Sobre la prueba de nivel",
    "lt_seo_1_h": "Cómo funciona la prueba",
    "lt_seo_1_p": "La prueba empieza con una pregunta de nivel intermedio. Si aciertas, la siguiente es más difícil; si fallas, más fácil. Tras 20 preguntas ha encontrado el punto en el que tus respuestas dejan de ser seguras, y ese es tu nivel estimado.",
    "lt_seo_2_h": "Qué evalúa",
    "lt_seo_2_p": "Las preguntas cubren gramática y vocabulario en contexto y la lectura de textos breves, desde avisos y mensajes en el nivel inicial hasta artículos y textos de opinión en el nivel avanzado. Tu resultado muestra cómo te ha ido en cada una de las tres destrezas y los temas en los que has perdido puntos.",
    "lt_seo_3_h": "Los niveles del MCER",
    "lt_seo_3_p": "Los niveles siguen el Marco Común Europeo de Referencia para las Lenguas, que usan escuelas, universidades y empresas en Europa y fuera de ella: A1 y A2 para usuarios básicos, B1 y B2 para usuarios independientes, y C1 y C2 para usuarios competentes.",
    "lt_seo_4_h": "Qué hacer con tu resultado",
    "lt_seo_4_p": "Con una cuenta gratuita de Alimun, tu nivel y tus temas se guardan y tu práctica empieza a partir de ellos. Cuando quieras, las clases en directo con un profesor te sitúan en un grupo de tu nivel.",
