    "careers_hero_title": "Enseñe desde cualquier lugar. Gane en sus propios términos.",
    "careers_hero_subtitle": "Dirija clases de conversación activa para estudiantes motivados en todo el mundo.",
    "careers_cta_apply": "Postularse como profesor",
    "careers_why_title": "¿Por qué enseñar en Alimun?",
    "careers_why_1_title": "Mayor alcance de los grupos",
    "careers_why_1_desc": "Olvídate de repetir la misma clase particular básica 20 veces. Enseña a un grupo estructurado y fomenta la interacción.",
    "careers_why_2_title": "Asistente de Calificación de IA",
    "careers_why_2_desc": "Nuestra IA maneja la revisión de vocabulario y gramática. Usted se enfoca en la conversación activa y comentarios en tiempo real.",
    "careers_why_3_title": "Ingresos Constantes",
    "careers_why_3_desc": "Reciba un pago base estable por grupo activo. A medida que sus grupos crecen, sus ganancias aumentan.",
    "careers_process_title": "Proceso de Selección",
    "careers_process_desc": "Aceptamos a menos del 5% de los candidatos para mantener nuestro estándar de enseñanza premium.",
    "careers_step_1_title": "Solicitud en línea",
    "careers_step_1_desc": "Envíe su CV, credenciales de enseñanza y una breve presentación en video de 2 minutos.",
    "careers_step_2_title": "Audición práctica",
    "careers_step_2_desc": "Dirija una sesión de práctica de 30 minutos con un grupo de estudiantes activos de Alimun.",
    "careers_step_3_title": "Lanzamiento de tu primer grupo",
    "careers_step_3_desc": "Complete la incorporación, elija sus horarios y lance su primer grupo de conversación oficial.",
    "careers_form_title": "Comience su Solicitud",
    "careers_form_desc": "Complete el formulario preliminar para solicitar un espacio de enseñanza.",
    "careers_form_language": "¿Qué idioma enseña?",
    "careers_form_experience": "Años de experiencia docente",
    "careers_form_video": "Enlace a video de presentación (Loom, YouTube, etc.)",
    "careers_form_submit": "Enviar Solicitud",
    "careers_hero_desc": "Enseña a tu manera. Alimun combina clases de conversación en vivo con retroalimentación impulsada por IA, automatizando todas las calificaciones para que puedas concentrarte por completo en la interacción en vivo con los estudiantes, la mentoría en grupos pequeños y la práctica activa.",
    "careers_t1_desc": "Diseñar el plan de estudios de los grupos en Alimun fue un cambio radical. Enseño a muchos estudiantes simultáneamente sin agotarme.",
    "careers_t2_desc": "La IA de Alimun se encarga de todos los ejercicios de vocabulario y las calificaciones. Dedico el 100% de mi tiempo de clase a lo que amo: ayudar a los estudiantes a hablar.",
    "careers_t3_desc": "El modelo de grupos de trabajo es mucho más interactivo y estimulante que repetir lecciones individuales todo el día.",
    "careers_t4_desc": "Las tarifas consistentes por grupo me brindan una excelente estabilidad de ingresos al tiempo que mantengo un horario completamente flexible.",
    "careers_cta_ready_title": "¿Listo para enseñar?",
    "careers_carousel_1": "¿Cansado de dar clases particulares repetitivas?",
    "careers_carousel_2": "¿Quieres escalar tu impacto?",
    "careers_carousel_3": "¿Quieres un horario flexible?",
    "careers_carousel_4": "Enseña en Alimun.",
    "careers_why_4_title": "Horarios Flexibles",
    "careers_why_4_desc": "Elige tu propia disponibilidad y horarios de clase. Enseña desde cualquier parte del mundo.",
    "careers_sim_sub_1": "¿Cansado de <span class=\"alimun-cta-highlight\">no ganar lo suficiente</span> con clases particulares?",
    "careers_sim_sub_2": "La mayoría de las plataformas cobran hasta un <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">33% de comisión</span>.",
    "careers_sim_sub_3": "En Alimun cobramos el <span class=\"alimun-cta-highlight\">30%</span>.",
    "careers_sim_sub_4": "¡Además, nuestro modelo te permite enseñar hasta a <span class=\"alimun-cta-highlight\">15 estudiantes</span> a la vez!",
    "careers_sim_sub_5": "La IA califica los deberes. <span class=\"alimun-cta-highlight\">Céntrate en la conversación directa</span>.",
    "careers_sim_sub_6": "Gana hasta <span class=\"alimun-cta-highlight\">80 €/hora</span> con total flexibilidad horaria.",
    "careers_sim_sub_7": "Habla con fluidez. De por vida. <span class=\"alimun-cta-highlight\">Enseña en Alimun</span>.",
    "corporate_hero_title": "soluciones corporativas",
    "corporate_hero_desc": "Asegúrate de que tu personal reubicado hable con fluidez desde el primer día. Alimun combina grupos profesionales específicos de cada rol con profesores nativos expertos y seguimiento de progreso por IA.",
    "corporate_cta_demo": "Solicitar demostración",
    "corporate_why_title": "Fluidez del personal",
    "corporate_why_1_title": "Profesores expertos en reubicación",
    "corporate_why_1_desc": "Expertos en idiomas nativos especializados en integración de expatriados, cultura empresarial local y conversación profesional.",
    "corporate_why_2_title": "Cohortes por funciones",
    "corporate_why_2_desc": "Los empleados aprenden juntos en grupos pequeños divididos por su función laboral, practicando escenarios reales del lugar de trabajo.",
    "corporate_why_3_title": "Progreso impulsado por IA",
    "corporate_why_3_desc": "Nuestro motor de IA automatiza los ejercicios de vocabulario y las calificaciones, maximizando la práctica de habla en vivo con los profesores.",
    "corporate_why_4_title": "Panel de administración de RRHH",
    "corporate_why_4_desc": "Realiza el seguimiento de la asistencia, horas de conversación activa e hitos de competencia del MCER con análisis en tiempo real.",
    "corporate_process_title": "Cómo funciona",
    "corporate_step_1_title": "1. Evaluación de habilidades",
    "corporate_step_1_desc": "Evaluamos el nivel de habla de tus empleados y los asignamos a sus destinos de reubicación.",
    "corporate_step_2_title": "2. Cohortes personalizadas",
    "corporate_step_2_desc": "Los empleados se unen a grupos de conversación corporativos privados que coinciden con su rol y metas lingüísticas.",
    "corporate_step_3_title": "3. Lanzamiento y seguimiento",
    "corporate_step_3_desc": "Las clases comienzan según tu horario y el departamento de RRHH recibe auditorías mensuales de progreso y asistencia.",
    "corporate_slide_1": "¿Trasladas a tu <span class=\"alimun-cta-highlight\">equipo al extranjero</span>?",
