    "corporate_form_submit": "Enviar solicitud →",
    "corporate_t1_desc": "Con 18 años de experiencia, Sarah se especializa en la preparación intensiva para la reubicación de ejecutivos corporativos que se mudan a España y Latinoamérica.",
    "corporate_t2_desc": "Jessica aporta 22 años de capacitación en idiomas, construyendo módulos de vocabulario a medida para equipos de soporte técnico, finanzas e ingeniería.",
    "corporate_t3_desc": "Lingüista cognitiva bilingüe con 15 años de asesoramiento. Martina lidera nuestros grupos de inmersión en reubicación y protocolo empresarial local.",
    "corporate_t4_desc": "Con 20 años de experiencia asesorando a ejecutivos multinacionales, Kevin dirige módulos de redacción comercial, presentaciones y negociación.",
