    "tiers_plan_1_desc": "Un cours en direct par semaine, les notes de séance avec le nouveau vocabulaire et l’accès à la communauté.",
    "tiers_plan_2_desc": "Deux cours en direct par semaine dans un groupe plus petit, un retour sur ton travail chaque semaine, des rédactions corrigées et un bilan de progression mensuel.",
    "tiers_plan_3_desc": "Trois cours en direct par semaine dans un groupe presque privé, une séance individuelle chaque semaine et un parcours conçu pour toi.",
    "tiers_plan_4_desc": "Des cours particuliers avec ton propre professeur, sur la base de trois cours par semaine, un programme construit autour de toi et des cours supplémentaires quand tu en as besoin.",
