    "corp_cta_chat": "Chatten Sie mit uns",
    "corp_cta_chat_desc": "Sprechen Sie mit unserem B2B-Team, um ein passendes Sprachtraining für Ihr Unternehmen zu entwerfen.",
    "corp_features_title": "Warum Alimun für Teams funktioniert",
    "corp_feature_1_title": "Rollenspezifische Lehrpläne",
