    "corp_tier_2_title": "Enterprise-Lizenz",
    "corp_tier_2_desc": "Vollständiger Zugriff für Ihre Organisation mit flexiblen Zeiten, Priority-Support und B2B-Abrechnung.",
    "corp_form_title": "Unternehmensanfrage",
    "corp_form_desc": "Teilen Sie uns Ihren Bedarf mit und wir senden Ihnen ein maßgeschneidertes Angebot.",
