    "services_tier_2_desc": "~17 Lerner – kleinere Gruppen & wöchentliches Feedback",
    "services_tier_3_desc": "~6 Lerner + 1:1 – fast privates Umfeld & wöchentliches 1-zu-1",
    "services_tier_4_desc": "Einzelunterricht (Basis 3 Klassen/Woche) – Option auf zusätzliche Stunden nach Limit",
    "tiers_hero_title": "Zugangsstufen",
    "tiers_hero_desc": "Finden Sie das richtige Maß an Aufmerksamkeit. Wir sind keine starre Schule – wählen Sie die Stufe, die zu Ihrem Budget und Ihrem Engagement passt, und wechseln Sie jederzeit, wenn sich Ihre Ziele ändern.",
