    "tiers_plan_1_desc": "Uma aula ao vivo por semana, anotações da sessão com o vocabulário novo e acesso à comunidade.",
    "tiers_plan_2_desc": "Duas aulas ao vivo por semana em uma turma menor, feedback sobre o seu trabalho toda semana, redações corrigidas e um relatório mensal de progresso.",
    "tiers_plan_3_desc": "Três aulas ao vivo por semana em uma turma quase particular, uma sessão individual toda semana e um percurso feito para você.",
    "tiers_plan_4_desc": "Aulas particulares com o seu próprio professor, com base em três aulas por semana, um programa feito em torno de você e aulas extras quando precisar.",
    "tiers_choose": "Escolher este plano",
    "tiers_hero_lead": "Aulas de idiomas ao vivo com um professor, a partir de €24 por mês. Escolha o tamanho da sua turma e quantas vezes por semana quer ter aula, e mude de plano quando os seus objetivos mudarem.",
    "tiers_hero_cta": "Ver os planos",
    "tiers_pc_title": "Quanto custa uma aula ao vivo",
    "tiers_pc_desc": "Escolha um plano para ver o preço de uma aula ao vivo, calculado a partir do preço mensal e das aulas que você tem em um mês de cerca de 4,3 semanas.",
    "tiers_pc_unit": "por aula ao vivo",
    "tiers_pc_line_1": "Uma aula ao vivo por semana, cerca de 4 por mês, por {price} por mês.",
