    "faq_a1": "一位老师带一个小组，所以每节课的费用由大家分摊。课与课之间，你的练习会立即批改，老师批改你的作业。",
    "faq_a2": "会的。老师引导对话，让每个人都有开口的时间，并实时纠正你，小组规模根据套餐约为 6 到 35 人。",
    "faq_a3": "每个班级每周在固定日子、固定时间上课，老师和同学都不变，所以请选择时间适合你的班级。课与课之间，你可以随时练习。",
    "faq_a4": "每位老师都需提交简历、资质和一段 2 分钟视频，并为一小组在读学员带一节 30 分钟的试讲课，通过后才开始授课。",
    "faq_a5": "按套餐安排与老师和小组一起上的直播课、课堂笔记、批改后的作业，以及带即时反馈的练习库、单词卡和考试题型练习。",
    "faq_a6": "在 alimun.com/signup 注册，完成简短的分级测试并选择套餐。目前开放英语和德语课程；其他语言可免费加入候补名单，开课时我们会发邮件通知你。",
