    "home_groups_title": "选择你的小组规模",
    "home_groups_desc": "每个套餐都有老师带领的直播课，每周固定时间上课。小组越小，你开口说话的时间就越多。",
    "home_groups_people": "人一组",
    "home_groups_private": "只有你和你的老师",
    "home_groups_month": "每月",
    "home_groups_1_desc": "每周一节直播课，小组约 35 人，并可加入学习社区。",
    "home_groups_2_desc": "每周两节直播课，小组约 17 人，每周都会收到对你作业的反馈。",
    "home_groups_3_desc": "每周三节直播课，小组约 6 人，另外每周一节一对一课程。",
    "home_groups_4_desc": "与老师一对一的私教课，基础为每周三节课，可另加课时。",
    "home_groups_cta": "比较套餐",
    "home_langs_title": "语言课程",
    "home_langs_desc": "由老师带领的直播课，从 A1 到 C2，课与课之间还有练习。选择你的语言，了解课程安排、级别、可以准备的证书和价格。",
    "home_seo_title": "跟着真人老师在线学语言",
    "home_seo_intro": "Alimun 是一所在线语言学校，每门课程都围绕老师带领的直播课展开。下面介绍上课方式和你可以期待的内容。",
    "home_seo_1_h": "在线直播课，而不是录播视频",
    "home_seo_1_p": "每节课都是由老师带领的视频直播课，<span class=\"sx_mark\">和同一批同学一起上</span>，每周固定日子、固定时间。你从第一节课就开口说话，老师随时纠正你；每节课后你会收到课堂笔记、新词汇和作业。",
    "home_seo_2_h": "课与课之间的练习",
    "home_seo_2_p": "两节课之间，你可以继续用<span class=\"sx_mark\">符合你水平、即时批改的练习</span>、包含课堂词汇的单词卡和考试题型的任务来练习。老师布置作业并批改后发还给你，附上分数、你的优点和需要改进的地方。",
    "home_seo_3_h": "价格合理的小组课",
    "home_seo_3_p": "在小组里，<span class=\"sx_mark\">每节课的费用由大家分摊</span>，所以直播课比私教便宜得多。你可以选择想要多少关注：约 35 人、17 人或 6 人的小组，或一对一私教课，每月 24 欧元起。",
    "home_seo_4_h": "从 A1 到 C2 的所有级别",
    "home_seo_4_p": "课程遵循欧洲语言共同参考框架，从入门到精通。简短的分级测试会<span class=\"sx_mark\">把你分到合适的小组</span>（A1 到 C1 之间），让你不必重复已经掌握的内容。你还可以练习英语 B2 First、C1 Advanced 和雅思，以及德语 Goethe B1、Goethe B2 和 telc B1 的考试题型。",
    "home_seo_5_h": "现已开设英语和德语，更多语言即将推出",
    "home_seo_5_p": "英语和德语课程现已开放。法语、西班牙语、意大利语和葡萄牙语即将推出，你可以<span class=\"sx_mark\">免费加入候补名单</span>，开课时第一时间收到通知。你只需要一台带摄像头和麦克风的电脑或其他设备：课程在浏览器中进行，并且可以随时取消。",
    "home_quiz_btn": "测一测你的水平",
    "home_quiz_pick": "选择你想测试的语言。大约需要两分钟，答对越多，句子就越难。",
