    "tiers_faq_title": "关于套餐和价格的问题",
    "tiers_faq_q1": "可以随时取消吗？",
    "tiers_faq_a1": "可以。你可以随时在账户的付款设置中取消，并可使用到已付费周期结束，详见条款与条件。",
    "tiers_faq_q2": "年付套餐怎么计算？",
    "tiers_faq_a2": "每年支付一次，只需付十个月的费用就能使用十二个月。例如 Community 每年 240 欧元，而不是每月 24 欧元。",
    "tiers_faq_q3": "以后可以更换套餐吗？",
    "tiers_faq_a3": "可以。目标变化时你可以换成其他套餐。如需帮助选择，请通过联系页面给我们留言。",
    "tiers_faq_q4": "用什么货币付款？",
    "tiers_faq_a4": "我们会尽量用你的货币显示价格，包括欧元、美元、加元、澳元或摩洛哥迪拉姆，你将以页面上显示的货币付款。",
    "tiers_faq_q5": "如果我的语言还没开课怎么办？",
    "tiers_faq_a5": "你可以免费加入候补名单，今天无需付款。你的语言一开课我们就会发邮件通知你，英语和德语课程已经开放。",
