    "corporate_form_submit": "提交预约 →",
    "corporate_t1_desc": "拥有 18 年教学经验，Sarah 专为外派至西班牙和拉美地区的企业高管提供高强度的语言和生活适应性培训。",
    "corporate_t2_desc": "Jessica 拥有 22 年企业语言培训经验，专为技术支持、金融和工程团队构建定制化的岗位词汇模块。",
    "corporate_t3_desc": "Martina 是一名拥有 15 年外派指导经验的双语认知语言学家，她主导的浸入式小班课程专注于当地商业礼仪。",
    "corporate_t4_desc": "Kevin 拥有 20 年辅导跨国企业高管的经验，他负责商务写作、演示演讲以及合同谈判等核心板块的强化培训。",
    "corporate_cta_text_1": "正在派遣员工到国外？",
    "corporate_cta_text_2": "需要母语专业教师？",
    "corporate_cta_text_3": "提升团队语言流利度。",
    "corporate_cta_text_4": "联系 Alimun 企业版。",
    "corp_huge_slide_1": "全球业务扩张 <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">需要全球化的语言流利度</span>。",
    "corp_huge_slide_2": "如果忽视 <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">语言储备</span>，94% 的国际派遣任务都会以失败告终。",
    "corp_huge_slide_3": "海外派遣失败代价高昂。语言储备是 <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">您最核心的安全保障</span>。",
    "corp_huge_slide_4": "双语团队能够与当地建立 <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">即时的信任和本地公信力</span>。",
    "corp_huge_slide_5": "流畅沟通能打通本地运营，<span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">将停工期和业务瓶颈降至最低</span>。",
    "corp_huge_slide_6": "通过 <span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">专业级别的企业定制小班课程</span> 赋能您的外派员工。",
    "corp_huge_slide_7": "流利表达。终生受益。<span class=\"alimun-cta-highlight\" style=\"background:#ceff65; color:#080808;\">Alimun Corporate</span>。",
    "cta_ready_to_learn": "准备好学习了吗？",
    "cta_phrase_1": "想要<span class=\"alimun-cta-highlight\">移居国外？</span>",
    "cta_phrase_2": "想要<span class=\"alimun-cta-highlight\">获得那份工作？</span>",
    "cta_phrase_3": "想要<span class=\"alimun-cta-highlight\">通过那场考试？</span>",
    "cta_phrase_4": "加入 <span class=\"alimun-cta-highlight\">Alimun。</span>",
    "cta_btn_join_alimun": "加入 alimun",
    "about_hero_title": "我们的故事",
    "about_hero_desc": "由语言老师创办：我们厌倦了看着优秀的学生在昂贵又不频繁的一对一课程中停滞不前。Alimun 把规律的直播课与即时批改的练习结合起来，让进步在课与课之间也能发生。",
    "about_btn_waitlist": "加入候补名单",
    "about_history_title": "真实流畅度标准",
    "about_history_desc": "从第一天起就围绕一个理念构建：如果由 AI 处理重复性的批改，优秀的老师可以同时指导多名学生。这一信念塑造了我们推出的每个级别、每门课程和每个功能。",
    "about_history_eyebrow": "我们的历史",
    "about_history_y1_desc": "Alimun 由语言教师创立",
    "about_history_y2_desc": "首个 AI 批改引擎上线",
    "about_history_y3_desc": "首批 200 名学员参与私测",
    "about_history_y4_desc": "每日班级候补名单公开发布",
    "about_staff_title": "结识我们的老师",
    "about_staff_1_desc": "Sarah 拥有 18 年的教学经验，负责设计 Community 级别的课程——旨在让零基础的学员从第一周起就养成真正的学习习惯。",
    "about_staff_2_desc": "Jessica 拥有 22 年的课堂教学经验，擅长帮助犹豫不决的中级学员转变为自信、流利的口语表达者。",
    "about_staff_3_desc": "Martina 是一位拥有 15 年教学经验的语言学家，负责主持我们的 Micro-Group 课程，以纠正阻碍学员进步的细微错误而闻名。",
    "about_staff_4_desc": "Kevin 拥有 20 年经验，负责我们的小班定制课程（Intensive 1:1），深受需要完全个性化计划和每周督学的学员喜爱。",
    "services_hero_title": "工具箱",
    "services_hero_desc": "每篇作文、每场测试和每份家庭作业在提交的瞬间即可获得批改。每天在直播课中练习口语，剩下的交给 AI 处理——即时反馈，无需等待答疑时间。",
    "services_btn_explore": "探索工具箱",
    "services_quote_text": "正是每日的反馈和真实的练习，让每位学员都获得了真正的优势。",
    "services_gallery_title": "我们的学习工具箱",
    "services_ai_title": "AI 功能",
    "services_ai_desc": "每个级别都包含相同的核心工具箱：AI 作文和作业批改、即时测试反馈、交互式口语和语法练习，以及展示下一步练习内容的进度面板。",
