    "lt_load_error": "Non è stato possibile caricare il test. Controlla la connessione e riprova.",
    "lt_exit_confirm": "Uscire dal test? Le tue risposte non verranno salvate.",
    "lt_focus_text": "In base alle tue risposte, inizieremmo da {topics}.",
    "lt_focus_top": "Hai risposto correttamente a tutte le domande. Inizieremmo con testi impegnativi e lessico avanzato.",
    "lt_and": "e",
    "lt_name_A1": "Principiante",
    "lt_name_A2": "Elementare",
    "lt_name_B1": "Intermedio",
    "lt_name_B2": "Intermedio superiore",
    "lt_name_C1": "Avanzato",
    "lt_name_C2": "Padronanza",
    "lt_desc_A1": "Comprendi e usi espressioni familiari di uso quotidiano e frasi molto semplici, sai presentarti e fare e rispondere a domande semplici.",
    "lt_desc_A2": "Comprendi espressioni frequenti su argomenti quotidiani e comunichi in attività semplici e di routine.",
    "lt_desc_B1": "Comprendi i punti principali di testi chiari su argomenti familiari, te la cavi nella maggior parte delle situazioni di viaggio e descrivi esperienze e progetti.",
    "lt_desc_B2": "Comprendi le idee principali di testi complessi, interagisci con una certa scioltezza e spontaneità e spieghi il tuo punto di vista su un tema di attualità.",
    "lt_desc_C1": "Comprendi un’ampia gamma di testi lunghi e impegnativi, ti esprimi con scioltezza e spontaneità e usi la lingua in modo flessibile in ambito sociale, accademico e professionale.",
    "lt_desc_C2": "Comprendi praticamente tutto ciò che leggi o ascolti, riassumi informazioni da fonti diverse e ti esprimi con grande scioltezza e precisione.",
