    "va_demo_teacher": "Enseignant démo (données d'exemple)",
    "va_demo_student": "Élève démo (données d'exemple)",
    "va_empty_teacher": "Aucun compte enseignant pour le moment, il n'y a donc rien à afficher. Un tableau de bord enseignant apparaîtra dès qu'un enseignant sera inscrit.",
    "va_empty_student": "Aucun compte élève pour le moment, il n'y a donc rien à afficher. Un tableau de bord élève apparaîtra dès qu'un élève sera inscrit.",
    "va_back": "Retour à l'admin",
    "student_oto_r_not_active": "Votre abonnement n'est pas actif.",
    "student_oto_r_no_teacher": "Votre classe n'a pas d'enseignant pour le moment.",
    "student_oto_r_before_first_lesson": "Votre premier suivi s'ouvre après votre premier cours.",
    "student_oto_r_booked": "Vous avez réservé le suivi de cette semaine.",
    "student_oto_r_window_closed": "La période de suivi de cette semaine est terminée. La suivante s'ouvre après votre prochain cours.",
    "student_oto_r_before_lesson_end": "Vous pourrez réserver le suivi une fois le cours terminé.",
    "student_oto_r_join_class_first": "Rejoignez d'abord une classe : les cours particuliers se réservent avec l'enseignant de votre classe.",
    "student_oto_e_slot_taken": "Ce créneau vient d'être pris. Choisissez-en un autre.",
    "student_oto_e_student_busy": "Vous avez déjà un 1:1 à cette heure-là.",
    "student_oto_e_no_credit": "Il ne vous reste aucun crédit 1:1. Achetez-en un pour réserver un cours particulier.",
