    "student_oto_e_not_found": "Réservation introuvable.",
    "student_oto_e_not_allowed": "Cette réservation n'est pas disponible avec votre formule.",
    "teacher_oto_e_not_found": "Réservation introuvable.",
    "teacher_oto_e_bad_note": "Écrivez une note de 4000 caractères maximum.",
    "teacher_oto_e_cancelled": "Cette réservation a été annulée.",
