    "careers_cta_apply": "Postuler comme enseignant",
    "careers_why_title": "Pourquoi enseigner sur Alimun ?",
    "careers_why_1_title": "Impact démultiplié",
    "careers_why_1_desc": "Ne répétez plus le même cours particulier de base 20 fois. Enseignez à un groupe structuré et laissez les apprenants interagir.",
    "careers_why_2_title": "Assistant de correction IA",
    "careers_why_2_desc": "Notre IA s'occupe de la vérification du vocabulaire et de la grammaire. Concentrez-vous sur la pratique orale en direct.",
    "careers_why_3_title": "Revenus réguliers",
    "careers_why_3_desc": "Recevez un tarif de base stable par groupe actif. Vos revenus augmentent à mesure que vos groupes grandissent.",
    "careers_process_title": "Processus de recrutement",
    "careers_process_desc": "Nous acceptons moins de 5% des candidats afin de maintenir une qualité d'enseignement premium.",
    "careers_step_1_title": "Candidature en ligne",
    "careers_step_1_desc": "Envoyez votre CV, vos diplômes et une courte vidéo de présentation de 2 minutes.",
    "careers_step_2_title": "Audition pratique",
    "careers_step_2_desc": "Animez une session pratique de 30 minutes avec un petit groupe d'apprenants actifs d'Alimun.",
    "careers_step_3_title": "Lancement de votre premier groupe",
    "careers_step_3_desc": "Finalisez l'intégration, fixez vos horaires et lancez votre premier groupe de conversation officiel.",
    "careers_form_title": "Commencez votre candidature",
    "careers_form_desc": "Remplissez ce formulaire préliminaire pour postuler.",
    "careers_form_language": "Quelle langue enseignez-vous ?",
    "careers_form_experience": "Années d'expérience d'enseignement",
    "careers_form_video": "Lien vers la vidéo de présentation (Loom, YouTube, etc.)",
    "careers_form_submit": "Envoyer la candidature",
    "careers_hero_desc": "Enseignez selon vos conditions. Alimun associe des cours de conversation en direct à des retours basés sur l'IA, automatisant toutes les corrections afin que vous puissiez vous concentrer entièrement sur l'interaction en direct avec les apprenants, le mentorat en sous-groupes et la pratique active.",
    "careers_t1_desc": "Concevoir le programme des groupes sur Alimun a changé la donne. J'enseigne à de nombreux apprenants simultanément sans m'épuiser.",
    "careers_t2_desc": "L'IA d'Alimun s'occupe de tous les exercices de vocabulaire et des corrections. Je consacre 100 % de mon temps de cours à ce que j'aime : aider les apprenants à parler.",
    "careers_t3_desc": "Le modèle d'apprentissage en groupe est bien plus interactif et stimulant que la répétition de cours individuels toute la journée.",
    "careers_t4_desc": "Les tarifs stables par groupe m'offrent une excellente sécurité financière tout en conservant un emploi du temps totalement flexible.",
    "careers_cta_ready_title": "Prêt à enseigner ?",
    "careers_carousel_1": "Fatigué des cours particuliers répétitifs ?",
    "careers_carousel_2": "Envie de démultiplier votre impact ?",
    "careers_carousel_3": "Envie d'un emploi du temps flexible ?",
    "careers_carousel_4": "Enseignez sur Alimun.",
    "careers_why_4_title": "Horaires Flexibles",
    "careers_why_4_desc": "Définissez votre propre disponibilité et vos horaires de cours. Enseignez depuis n'importe où dans le monde.",
    "careers_sim_sub_1": "Fatigué de <span class=\"alimun-cta-highlight\">ne pas gagner assez</span> avec les cours particuliers ?",
    "careers_sim_sub_2": "La plupart des plateformes prélèvent jusqu'à <span class=\"alimun-cta-highlight\" style=\"background:#ff6565; color:#fff; box-shadow:none;\">33 % de commission</span>.",
    "careers_sim_sub_3": "Chez Alimun, c'est <span class=\"alimun-cta-highlight\">30%</span>.",
    "careers_sim_sub_4": "De plus, notre modèle vous permet d'enseigner à <span class=\"alimun-cta-highlight\">15 élèves</span> en même temps !",
    "careers_sim_sub_5": "L'assistant IA s'occupe des corrections. <span class=\"alimun-cta-highlight\">Concentrez-vous sur l'oral</span>.",
    "careers_sim_sub_6": "Gagnez jusqu'à <span class=\"alimun-cta-highlight\">80 €/heure</span> avec une flexibilité totale.",
    "careers_sim_sub_7": "Parlez couramment. Pour la vie. <span class=\"alimun-cta-highlight\">Enseignez sur Alimun</span>.",
    "corporate_hero_title": "solutions entreprise",
    "corporate_hero_desc": "Assurez-vous que vos employés relocalisés parlent couramment dès le premier jour. Alimun associe des cours collectifs professionnels par métier à des enseignants natifs spécialisés et un suivi par IA.",
    "corporate_cta_demo": "Demander une démo",
    "corporate_why_title": "Maîtrise des équipes",
    "corporate_why_1_title": "Enseignants experts en expatriation",
    "corporate_why_1_desc": "Experts linguistiques natifs spécialisés dans l'intégration des expatriés, la culture d'entreprise locale et la conversation professionnelle.",
    "corporate_why_2_title": "Cours collectifs par métier",
    "corporate_why_2_desc": "Les collaborateurs apprennent ensemble en petits groupes organisés par fonction, en simulant des situations professionnelles concrètes.",
    "corporate_why_3_title": "Progression assistée par IA",
    "corporate_why_3_desc": "Notre moteur d'IA automatise l'apprentissage du vocabulaire et les corrections, libérant du temps pour la pratique orale avec l'enseignant.",
    "corporate_why_4_title": "Tableau de bord RH",
    "corporate_why_4_desc": "Suivez les présences, les heures de conversation active et les étapes clés du CECRL grâce à des analyses en temps réel.",
    "corporate_process_title": "Comment ça marche",
    "corporate_step_1_title": "1. Évaluation des compétences",
    "corporate_step_1_desc": "Nous évaluons le niveau d'expression orale de vos employés et les associons à leurs destinations de relocalisation.",
    "corporate_step_2_title": "2. Groupes sur-mesure",
    "corporate_step_2_desc": "Les employés rejoignent des groupes de conversation privés adaptés à leur fonction et à leurs objectifs.",
    "corporate_step_3_title": "3. Lancement et suivi",
    "corporate_step_3_desc": "Les cours commencent selon votre calendrier, et les RH reçoivent chaque mois des rapports détaillés de présence et de progression.",
    "corporate_slide_1": "Vous envoyez votre <span class=\"alimun-cta-highlight\">équipe à l’étranger</span> ?",
